-- Mutual Fund sample data load for Azure SQL database MFTransDev
-- Generated from sample_data/source CSV files.
-- Run after sql/azure_sql_schema.sql has created the tables.
-- This script is idempotent for demo use: it deletes existing sample rows, then reloads them.

SET NOCOUNT ON;

PRINT 'Deleting existing sample data in foreign-key order';
DELETE FROM dbo.Asset;
DELETE FROM dbo.Commission;
DELETE FROM dbo.Holding;
DELETE FROM dbo.[Transaction];
DELETE FROM dbo.Price;
DELETE FROM dbo.Investor;
DELETE FROM dbo.Fund;
DELETE FROM dbo.Agent;

PRINT 'Loading Agent.csv into dbo.Agent';
SET IDENTITY_INSERT dbo.Agent ON;
SET IDENTITY_INSERT dbo.Agent OFF;

PRINT 'Loading Fund.csv into dbo.Fund';
SET IDENTITY_INSERT dbo.Fund ON;
SET IDENTITY_INSERT dbo.Fund OFF;

PRINT 'Loading Investor.csv into dbo.Investor';
SET IDENTITY_INSERT dbo.Investor ON;
SET IDENTITY_INSERT dbo.Investor OFF;

PRINT 'Loading Price.csv into dbo.Price';
SET IDENTITY_INSERT dbo.Price ON;
SET IDENTITY_INSERT dbo.Price OFF;

PRINT 'Loading Transaction.csv into dbo.[Transaction]';
SET IDENTITY_INSERT dbo.[Transaction] ON;
SET IDENTITY_INSERT dbo.[Transaction] OFF;

PRINT 'Loading Holding.csv into dbo.Holding';
SET IDENTITY_INSERT dbo.Holding ON;
SET IDENTITY_INSERT dbo.Holding OFF;

PRINT 'Loading Commission.csv into dbo.Commission';
SET IDENTITY_INSERT dbo.Commission ON;
SET IDENTITY_INSERT dbo.Commission OFF;

PRINT 'Loading Asset.csv into dbo.Asset';
SET IDENTITY_INSERT dbo.Asset ON;
SET IDENTITY_INSERT dbo.Asset OFF;

PRINT 'Load complete. Row counts:';
SELECT 'Agent' AS table_name, COUNT(*) AS row_count FROM dbo.Agent
UNION ALL SELECT 'Fund', COUNT(*) FROM dbo.Fund
UNION ALL SELECT 'Investor', COUNT(*) FROM dbo.Investor
UNION ALL SELECT 'Price', COUNT(*) FROM dbo.Price
UNION ALL SELECT 'Transaction', COUNT(*) FROM dbo.[Transaction]
UNION ALL SELECT 'Holding', COUNT(*) FROM dbo.Holding
UNION ALL SELECT 'Commission', COUNT(*) FROM dbo.Commission
UNION ALL SELECT 'Asset', COUNT(*) FROM dbo.Asset
ORDER BY table_name;
